let tank = flow.get('sim_tank') ?? 15;
let riverOk = flow.get('sim_river') ?? true;
let pumpState = flow.get('pump_relay_state') ?? false;

if (pumpState) {
    tank = Math.min(100, tank + 2);
} else {
    tank = Math.max(10, tank - 0.2);
}
flow.set('sim_tank', tank);

msg.payload = {
    tank_level_pct: Math.round(tank),
    river_level_ok: riverOk,
    hose_flow_rate_lpm: pumpState ? 18.5 : 0.0,
    manual_mode: "AUTO"
};

return msg;

let state = context.get('state') || 'IDLE';
let pumpStartedAt = context.get('pumpStartedAt') || null;
let faultReason = context.get('faultReason') || null;

const TANK_START_PCT = 20;
const TANK_STOP_PCT  = 95;
const MAX_RUN_TIME_MS = 60 * 60 * 1000;
const FLOW_CHECK_DELAY_MS = 15 * 1000;

const data = msg.payload || {};
const tankLevel = Number(data.tank_level_pct ?? 50);
const riverOk   = Boolean(data.river_level_ok ?? true);
const flowRate  = Number(data.hose_flow_rate_lpm ?? 0);
const mode      = data.manual_mode || 'AUTO';

if (data.reset_fault === true) {
    state = 'IDLE';
    faultReason = null;
    pumpStartedAt = null;
}

let pumpCmd = false;

if (state === 'FAULT') {
    pumpCmd = false;
} else if (mode === 'MANUAL_OFF') {
    state = 'IDLE';
    pumpCmd = false;
    pumpStartedAt = null;
} else if (mode === 'MANUAL_ON') {
    if (!riverOk) {
        state = 'FAULT';
        faultReason = 'River dry-run protection triggered.';
        pumpCmd = false;
    } else {
        state = 'PUMPING';
        pumpCmd = true;
        if (!pumpStartedAt) pumpStartedAt = Date.now();
    }
} else {
    if (!riverOk) {
        if (state === 'PUMPING') {
            state = 'FAULT';
            faultReason = 'River water level dropped below suction intake.';
        }
        pumpCmd = false;
        pumpStartedAt = null;
    } else {
        if (state === 'IDLE' && tankLevel <= TANK_START_PCT) {
            state = 'PUMPING';
            pumpStartedAt = Date.now();
        } else if (state === 'PUMPING' && tankLevel >= TANK_STOP_PCT) {
            state = 'IDLE';
            pumpStartedAt = null;
        }
        pumpCmd = (state === 'PUMPING');
    }
}

if (pumpCmd && pumpStartedAt) {
    const elapsed = Date.now() - pumpStartedAt;
    if (elapsed > FLOW_CHECK_DELAY_MS && flowRate < 1.0) {
        state = 'FAULT';
        faultReason = 'No water flow in hose after 15s. Check hose connection/pump prime!';
        pumpCmd = false;
        pumpStartedAt = null;
    }
    if (elapsed > MAX_RUN_TIME_MS) {
        state = 'FAULT';
        faultReason = 'Safety cutoff: Max continuous runtime exceeded.';
        pumpCmd = false;
        pumpStartedAt = null;
    }
}

context.set('state', state);
context.set('pumpStartedAt', pumpStartedAt);
context.set('faultReason', faultReason);
flow.set('pump_relay_state', pumpCmd);

let msgPump = {
    payload: pumpCmd,
    topic: "river_system/actuator/pump_relay"
};

let msgStatus = {
    payload: {
        state: state,
        pump_active: pumpCmd,
        tank_level_pct: tankLevel,
        river_water_ok: riverOk,
        hose_flow_lpm: flowRate,
        fault: faultReason,
        run_seconds: pumpStartedAt ? Math.round((Date.now() - pumpStartedAt)/1000) : 0,
        timestamp: new Date().toISOString()
    },
    topic: "river_system/telemetry/status"
};

return [msgPump, msgStatus];

const s = msg.payload || {};
return [{payload: Number(s.level_pct || 0)},
        {payload: (s.pump ? 'PUMP ON' : 'pump off') + ' . ' + (s.state || '') + (s.fault ? ' . FAULT ' + s.fault : '')}];
